00064     public static function getMenuApache()
00065     {
00066         global $bearsamppBins, $bearsamppLang;
00067         $resultItems = $resultActions = '';
00068 
00069         $isEnabled = $bearsamppBins->getApache()->isEnable();
00070 
00071         // Download
00072         $resultItems .= TplAestan::getItemLink(
00073             $bearsamppLang->getValue(Lang::DOWNLOAD_MORE),
00074             HttpClient::getWebsiteUrl('module/apache', '#releases'),
00075             false,
00076             TplAestan::GLYPH_BROWSER
00077         ) . PHP_EOL;
00078 
00079         // Enable
00080         $tplEnable = TplApp::getActionMulti(
00081             self::ACTION_ENABLE, array($isEnabled ? Config::DISABLED : Config::ENABLED),
00082             array($bearsamppLang->getValue(Lang::MENU_ENABLE), $isEnabled ? TplAestan::GLYPH_CHECK : ''),
00083             false, get_called_class()
00084         );
00085         $resultItems .= $tplEnable[TplApp::SECTION_CALL] . PHP_EOL;
00086         $resultActions .= $tplEnable[TplApp::SECTION_CONTENT] . PHP_EOL;
00087 
00088         if ($isEnabled) {
00089             $resultItems .= TplAestan::getItemSeparator() . PHP_EOL;
00090 
00091             // Versions
00092             $tplVersions = TplApp::getMenu($bearsamppLang->getValue(Lang::VERSIONS), self::MENU_VERSIONS, get_called_class());
00093             $resultItems .= $tplVersions[TplApp::SECTION_CALL] . PHP_EOL;
00094             $resultActions .= $tplVersions[TplApp::SECTION_CONTENT] . PHP_EOL;
00095 
00096             // Service
00097             $tplService = TplApp::getMenu($bearsamppLang->getValue(Lang::SERVICE), self::MENU_SERVICE, get_called_class());
00098             $resultItems .= $tplService[TplApp::SECTION_CALL] . PHP_EOL;
00099             $resultActions .= $tplService[TplApp::SECTION_CONTENT] . PHP_EOL;
00100 
00101             // Debug
00102             $tplDebug = TplApp::getMenu($bearsamppLang->getValue(Lang::DEBUG), self::MENU_DEBUG, get_called_class());
00103             $resultItems .= $tplDebug[TplApp::SECTION_CALL] . PHP_EOL;
00104             $resultActions .= $tplDebug[TplApp::SECTION_CONTENT] . PHP_EOL;
00105 
00106             // Modules
00107             $tplModules = TplApp::getMenu($bearsamppLang->getValue(Lang::MODULES), self::MENU_MODULES, get_called_class());
00108             $resultItems .= $tplModules[TplApp::SECTION_CALL] . PHP_EOL;
00109             $resultActions .= $tplModules[TplApp::SECTION_CONTENT] . PHP_EOL;
00110 
00111             // Alias
00112             $tplAlias = TplApp::getMenu($bearsamppLang->getValue(Lang::ALIASES), self::MENU_ALIAS, get_called_class());
00113             $resultItems .= $tplAlias[TplApp::SECTION_CALL] . PHP_EOL;
00114             $resultActions .= $tplAlias[TplApp::SECTION_CONTENT] . PHP_EOL;
00115 
00116             // Vhosts
00117             $tplVhosts = TplApp::getMenu($bearsamppLang->getValue(Lang::VIRTUAL_HOSTS), self::MENU_VHOSTS, get_called_class());
00118             $resultItems .= $tplVhosts[TplApp::SECTION_CALL] . PHP_EOL;
00119             $resultActions .= $tplVhosts[TplApp::SECTION_CONTENT] . PHP_EOL;
00120 
00121             // Conf
00122             $resultItems .= TplAestan::getItemNotepad(basename($bearsamppBins->getApache()->getConf()), $bearsamppBins->getApache()->getConf()) . PHP_EOL;
00123 
00124             // Access log
00125             $resultItems .= TplAestan::getItemNotepad($bearsamppLang->getValue(Lang::MENU_ACCESS_LOGS), $bearsamppBins->getApache()->getAccessLog()) . PHP_EOL;
00126 
00127             // Rewrite log
00128             $resultItems .= TplAestan::getItemNotepad($bearsamppLang->getValue(Lang::MENU_REWRITE_LOGS), $bearsamppBins->getApache()->getRewriteLog()) . PHP_EOL;
00129 
