00144     public static function getMenuApacheVersions()
00145     {
00146         global $bearsamppBins;
00147         $items = '';
00148         $actions = '';
00149 
00150         foreach ($bearsamppBins->getApache()->getVersionList() as $version) {
00151             $glyph = '';
00152             $apachePhpModule = $bearsamppBins->getPhp()->getApacheModule($version);
00153             if ($apachePhpModule === false) {
00154                 $glyph = TplAestan::GLYPH_WARNING;
00155             } elseif ($version == $bearsamppBins->getApache()->getVersion()) {
00156                 $glyph = TplAestan::GLYPH_CHECK;
00157             }
00158 
00159             $tplSwitchApacheVersion = TplApp::getActionMulti(
00160                 self::ACTION_SWITCH_VERSION, array($version),
00161                 array($version, $glyph),
00162                 false, get_called_class()
00163             );
00164 
00165             // Item
00166             $items .= $tplSwitchApacheVersion[TplApp::SECTION_CALL] . PHP_EOL;
00167 
00168             // Action
00169             $actions .= PHP_EOL . $tplSwitchApacheVersion[TplApp::SECTION_CONTENT];
00170         }
00171 
00172         return $items . $actions;
00173     }
