00215     public static function getMenuApacheService()
00216     {
00217         global $bearsamppRoot, $bearsamppLang, $bearsamppBins;
00218 
00219         $tplChangePort = TplApp::getActionMulti(
00220             self::ACTION_CHANGE_PORT, null,
00221             array($bearsamppLang->getValue(Lang::MENU_CHANGE_PORT), TplAestan::GLYPH_NETWORK),
00222             false, get_called_class()
00223         );
00224 
00225         $result = TplAestan::getItemActionServiceStart($bearsamppBins->getApache()->getService()->getName()) . PHP_EOL .
00226             TplAestan::getItemActionServiceStop($bearsamppBins->getApache()->getService()->getName()) . PHP_EOL .
00227             TplAestan::getItemActionServiceRestart($bearsamppBins->getApache()->getService()->getName()) . PHP_EOL .
00228             TplAestan::getItemSeparator() . PHP_EOL .
00229             TplApp::getActionRun(
00230                 Action::CHECK_PORT, array($bearsamppBins->getApache()->getName(), $bearsamppBins->getApache()->getPort()),
00231                 array(sprintf($bearsamppLang->getValue(Lang::MENU_CHECK_PORT), $bearsamppBins->getApache()->getPort()), TplAestan::GLYPH_LIGHT)
00232             ) . PHP_EOL .
00233             TplApp::getActionRun(
00234                 Action::CHECK_PORT, array($bearsamppBins->getApache()->getName(), $bearsamppBins->getApache()->getSslPort(), true),
00235                 array(sprintf($bearsamppLang->getValue(Lang::MENU_CHECK_PORT), $bearsamppBins->getApache()->getSslPort()) . ' (SSL)', TplAestan::GLYPH_RED_LIGHT)
00236             ) . PHP_EOL .
00237             $tplChangePort[TplApp::SECTION_CALL] . PHP_EOL .
00238             TplAestan::getItemNotepad($bearsamppLang->getValue(Lang::MENU_UPDATE_ENV_PATH), Path::getRootPath() . '/nssmEnvPaths.dat') . PHP_EOL;
00239 
00240         $isInstalled = $bearsamppBins->getApache()->getService()->isInstalled();
00241         if (!$isInstalled) {
00242             $tplInstallService = TplApp::getActionMulti(
00243                 self::ACTION_INSTALL_SERVICE, null,
00244                 array($bearsamppLang->getValue(Lang::MENU_INSTALL_SERVICE), TplAestan::GLYPH_SERVICE_INSTALL),
00245                 $isInstalled, get_called_class()
00246             );
00247 
00248             $result .= $tplInstallService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00249                 $tplInstallService[TplApp::SECTION_CONTENT] . PHP_EOL;
00250         } else {
00251             $tplRemoveService = TplApp::getActionMulti(
00252                 self::ACTION_REMOVE_SERVICE, null,
00253                 array($bearsamppLang->getValue(Lang::MENU_REMOVE_SERVICE), TplAestan::GLYPH_SERVICE_REMOVE),
00254                 !$isInstalled, get_called_class()
00255             );
00256 
00257             $result .= $tplRemoveService[TplApp::SECTION_CALL] . PHP_EOL . PHP_EOL .
00258                 $tplRemoveService[TplApp::SECTION_CONTENT] . PHP_EOL;
00259         }
00260 
00261         $result .= $tplChangePort[TplApp::SECTION_CONTENT] . PHP_EOL;
00262 
00263         return $result;
00264     }
