00381     public static function getActionSwitchApacheModule($module, $switch)
00382     {
00383         $switch = $switch == ActionSwitchApacheModule::SWITCH_OFF ? ActionSwitchApacheModule::SWITCH_ON : ActionSwitchApacheModule::SWITCH_OFF;
00384         return TplApp::getActionRun(Action::SWITCH_APACHE_MODULE, array($module, $switch)) . PHP_EOL .
00385             TplService::getActionRestart(BinApache::SERVICE_NAME) . PHP_EOL .
00386             TplAppReload::getActionReload() . PHP_EOL;
